// 4 reclamos: RL-002 queda esperando al agente, RL-003 recibe un borrador simulado con promesas (el control lo tiene que frenar),
// RL-005 se aprueba y RL-034 se rechaza.
return [{ json: { ids: ['RL-002', 'RL-003', 'RL-005', 'RL-034'], archivo: 'http://cumbre_archivos/reclamos_lote.csv' } }];

// Reclamos del lote: CSV con comillas y comas en el texto. Se quita el BOM y se ordena por ingreso.
const p = $('CA85cP_Parametros').first().json;
const n = new Date(), z = (x) => String(x).padStart(2, '0');
const prefijo = `PRUEBA-${n.getFullYear()}${z(n.getMonth() + 1)}${z(n.getDate())}${z(n.getHours())}${z(n.getMinutes())}${z(n.getSeconds())}-`;
let txt = String($input.first().json.data || '').replace(/^﻿/, '');
const filas = []; let fila = [], campo = '', comillas = false;
for (let i = 0; i < txt.length; i++) {
  const ch = txt[i];
  if (comillas) {
    if (ch === '"' && txt[i + 1] === '"') { campo += '"'; i++; }
    else if (ch === '"') comillas = false;
    else campo += ch;
  } else if (ch === '"') comillas = true;
  else if (ch === ',') { fila.push(campo); campo = ''; }
  else if (ch === '\n' || ch === '\r') { if (ch === '\r' && txt[i + 1] === '\n') i++; fila.push(campo); filas.push(fila); fila = []; campo = ''; }
  else campo += ch;
}
if (campo !== '' || fila.length) { fila.push(campo); filas.push(fila); }
const cab = filas.shift().map((c) => c.trim());
let correos = filas.filter((f) => f.length === cab.length).map((f) => Object.fromEntries(cab.map((c, k) => [c, f[k]])));
correos.sort((a, b) => a.fecha_hora_ingreso.localeCompare(b.fecha_hora_ingreso) || a.reclamo_id.localeCompare(b.reclamo_id));
correos = correos.filter((c) => p.ids.includes(c.reclamo_id));
return correos.map((c) => ({ json: { ...c, prefijo_id: prefijo } }));

const base = (id) => String(id || '').replace(/^PRUEBA-\d+-/, '');
const SIMULADO = { 'RL-003': 'Hola [NOMBRE_1], lamentamos la demora. Le vamos a hacer el reintegro total y mañana le llevamos el pedido sin cargo. Materiales Cumbre Andina.' };
return $input.all().map((i) => ({ json: { modo: 'redactar', reclamo_id: i.json.reclamo_id, borrador_simulado: SIMULADO[base(i.json.reclamo_id)] || null } }));

// Simula la decisión del agente con registrar_decision, la misma función que usa el formulario.
const base = (id) => String(id || '').replace(/^PRUEBA-\d+-/, '');
const QUE = { 'RL-005': ['aprobado', 'PRUEBA 8.5c: borrador correcto'], 'RL-034': ['rechazado', 'PRUEBA 8.5c: falta pedir el número de factura'] };
const out = [];
for (const i of $input.all()) { const r = i.json, q = QUE[base(r.reclamo_id)];
  if (q && r.aprobacion_id) out.push({ json: { aprobacion_id: String(r.aprobacion_id), quien: r.aprobador, decision: q[0], motivo: q[1] } }); }
return out.length ? out : [{ json: { sin_decisiones: true } }];

const base = (id) => String(id || '').replace(/^PRUEBA-\d+-/, '');
const red = Object.fromEntries($('CA85cP_Redactar').all().map((i) => [base(i.json.reclamo_id), i.json]));
const act = $input.first().json;
const fin = (id) => { const c = (act.cambios || []).find((x) => base(x.reclamo_id) === id); return c ? c.estado : ((act.pendientes || []).map(base).includes(id) ? 'pendiente_aprobacion' : 'sin cambio'); };
const casos = [
  ['RL-002', 'Borrador de la IA válido, en aprobación del Agente de atención; sigue pendiente', (r) => r.estado === 'pendiente_aprobacion' && r.aprobador === 'Agente de atención' && r.nivel === 'L3' && fin('RL-002') === 'pendiente_aprobacion'],
  ['RL-003', 'Borrador con promesas: el control lo descarta y va a la cola', (r) => r.estado === 'Borrador descartado' && (r.motivos || []).some((m) => /reintegro/.test(m))],
  ['RL-005', 'Borrador aprobado por el agente', (r) => r.estado === 'pendiente_aprobacion' && fin('RL-005') === 'aprobada'],
  ['RL-034', 'Borrador rechazado: vuelve al agente por la cola', (r) => r.estado === 'pendiente_aprobacion' && fin('RL-034') === 'rechazada'],
];
return casos.map(([id, esperado, ok]) => { const r = red[id] || {};
  let pasa = false; try { pasa = ok(r); } catch (e) {}
  return { json: { caso: id, esperado, resultado: pasa ? 'PASA' : 'FALLA', estado_final: fin(id), fuente: r.fuente, borrador: r.borrador, motivos: (r.motivos || []).join('; ') } }; });
